  a.label('Ivo · trabalho de entregador',58,4.5,-103);
  const foods={rita:{key:'bolo',name:'Bolo caseiro',price:12,fill:35},dito:{key:'carne',name:'Carne assada',price:25,fill:65},lia:{key:'cocada',name:'Cocada',price:8,fill:25}};
  function house(x,z,color,name){const g=group(x,z);box(12,4.5,12,color,0,2.4,0,g);box(12.8,.3,13,'#a46646',0,4.8,0,g);box(1.4,2.8,.1,'#775b46',0,1.7,6.1,g);for(const xx of [-3.5,3.5]){box(2.1,1.7,.1,'#e5e0ce',xx,2.8,6.1,g);box(1.8,1.4,.12,'#5e7c84',xx,2.8,6.2,g);}board(g,name,4,4,6.2);obstacles.push({x,z,w:12,d:12});mapBuildings.push({x,z,w:12,d:12,h:5,color});}
  house(-117,38,'#b8c9b6','CASA DA ROSA');house(113,44,'#d5bca1','CASA DA LURDES');house(-118,-45,'#d0cda5','CASA DO JUCA');
  const rosa=npc('rosa','Rosa','MORADORA · ENCOMENDAS',-117,47,'#b57b88');
  const lurdes=npc('lurdes','Dona Lurdes','MORADORA · ÁRVORE CAÍDA',113,54,'#9b8b5c');
  const juca=npc('juca','Juca','MORADOR · ENCOMENDAS',-118,-36,'#517e91');
  for(const x of [104,122]){box(.2,1.6,19,'#c1b398',x,1.0,53);obstacles.push({x,z:53,w:.3,d:19});}
  box(18,1.6,.2,'#c1b398',113,1,43.5);obstacles.push({x:113,z:43.5,w:18,d:.3});
  for(const x of [107,119]){box(5,1.6,.2,'#c1b398',x,1.0,62);obstacles.push({x,z:62,w:5,d:.3});}
  const fallen=group(113,61);const log=cylinder(.55,.67,8,'#755239',0,.88,0,fallen,14);log.rotation.z=Math.PI/2;const end=cylinder(.49,.49,.02,'#c9a06c',4.01,.88,0,fallen,14);end.rotation.z=Math.PI/2;for(let i=0;i<7;i++){const branch=cylinder(.07,.16,2.8,'#755239',-2+i*.65,1.15,(i%2?1:-1)*.6,fallen);branch.rotation.x=(i%2?1:-1)*1.1;ball(.8,'#5b7545',-2+i*.65,1.2,(i%2?1:-1)*1.8,fallen);}const treeObstacle={x:113,z:61,w:9,d:3.3,active:!s().treeCleared};obstacles.push(treeObstacle);fallen.visible=!s().treeCleared;
  const lenhador=npc('lenhador','Bento','LENHADOR · CORTE POR 50 MOEDAS',106,71,'#ad6049',true);
  const axe=new T.Group();box(.065,.9,.065,'#b49a65',0,0,0,axe);box(.36,.27,.09,'#8d9e9c',.12,.35,0,axe);lenhador.p.arms[1].add(axe);axe.position.set(0,-.47,.2);axe.visible=false;
  const bia=npc('bia','Bia','TRANSPORTE · BICICLETAS',20,61,'#729f9a');
