  function hud(){const st=s();$('health-value').textContent=Math.ceil(st.health)+' / 100';$('health-bar').style.width=st.health+'%';$('hunger-value').textContent=st.hunger+'%';$('hunger-bar').style.width=st.hunger+'%';$('recovery').textContent=st.health<100?(st.hunger===100?'Recuperando vida':'Coma até 100% para curar'):'Vida completa';$('transport-label').textContent=st.transport==='bike'?'Bicicleta':'A pé';$('job-panel').hidden=!st.delivery;if(st.delivery){$('job-title').textContent='Entrega para '+addresses[st.delivery.to].name;$('job-status').textContent=st.delivery.kind==='tree'&&!st.treeCleared?(st.treePaid?'Bento cortando · '+Math.ceil(st.chopRemaining)+' s':'Chame Bento · corte por 50 moedas'):'Siga o destino azul · E para entregar';}a.crate.visible=st.carrying||!!st.delivery;}
  return {sync(){treeObstacle.active=!s().treeCleared;fallen.visible=!s().inTunnel&&!s().treeCleared;axe.visible=!s().inTunnel&&s().treePaid&&!s().treeCleared;},quests,handle,update,updateDeath,hud,damage,respawn,buyFood,acceptJob,hire,setTransport,transportMenu,deliveryTarget,get dead(){return dead;},get immunity(){return immunity;},npcs:{ivo,rita,dito,lia,rosa,lurdes,juca,lenhador,bia,nando,joaquim},treeObstacle};
